const CACHE_NAME = "signalsafe-product-2.1.0";
const ASSETS = ["./","./index.html","./VERSION.json","./test-guide.html","./market-feasibility.html","./research-control.html","./compat.mjs","./bootstrap.mjs","./questions.mjs","./study-v2.mjs","./study-fixtures.mjs","./research.mjs","./research-consent.mjs","./research-consent-state.mjs","./pilot-protocol.mjs","./market-feasibility.mjs","./scoring.mjs","./storage.mjs","./manifest.webmanifest","./icon.svg","./styles/01.css","./styles/02.css","./styles/03-v03.css","./styles/04-v03-insights.css","./styles/05-v031-consent.css","./styles/06-v032-pilot.css","./styles/07-v2.css","./styles/08-v201.css","./styles/09-v21.css","./app-parts/app-core.js","./app-parts/app-home.js","./app-parts/app-quick.js","./app-parts/app-assessment.js","./app-parts/app-insights.js","./app-parts/app-runtime.js","./app-parts/app-v03.js","./app-parts/app-v03-insights.js","./app-parts/app-v03-feedback.js","./app-parts/app-v031-consent.js","./app-parts/app-v031-consent-state.js","./app-parts/app-v032-pilot.js","./app-parts/app-v033-market.js","./app-parts/app-v034-export.js","./app-parts/app-v2.js","./app-parts/app-v201.js","./app-parts/app-v21.js","./question-data/shared.mjs","./question-data/quick.mjs","./question-data/pre-a.mjs","./question-data/pre-b.mjs","./question-data/training-a.mjs","./question-data/training-b.mjs","./question-data/post-a.mjs","./question-data/post-b.mjs"];
self.addEventListener("install",event=>{event.waitUntil(caches.open(CACHE_NAME).then(cache=>cache.addAll(ASSETS)));self.skipWaiting();});
self.addEventListener("activate",event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key!==CACHE_NAME).map(key=>caches.delete(key)))));self.clients.claim();});
self.addEventListener("fetch",event=>{if(event.request.method!=="GET")return;const requestUrl=new URL(event.request.url);if(requestUrl.origin!==self.location.origin)return;event.respondWith(fetch(event.request).then(response=>{if(response.ok){const copy=response.clone();caches.open(CACHE_NAME).then(cache=>cache.put(event.request,copy)).catch(()=>{});}return response;}).catch(()=>caches.match(event.request).then(cached=>cached||((event.request.mode==="navigate")?caches.match("./index.html"):undefined))));});
